		this._rootMesh.addChild(this._lineBoundingBox);
		this.setColor(color);
		this._rotateAnchorsParent = new TransformNode("", gizmoLayer.utilityLayerScene);
		this._rotateAnchorsParent.rotationQuaternion = new Quaternion();
