						if (this.attachedMesh.isUsingPivotMatrix()) this._anchorMesh.position.copyFrom(this.attachedMesh.position);
						this._anchorMesh.addChild(this.attachedMesh);
						if (this._anchorMesh.getScene().useRightHandedSystem) this._tmpQuaternion.conjugateInPlace();
						this._tmpQuaternion.normalize();
						this._anchorMesh.rotationQuaternion.multiplyToRef(this._tmpQuaternion, this._anchorMesh.rotationQuaternion);
